package com.exemplo.crud;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.Collection;
import java.util.Map;
import java.util.concurrent.ConcurrentSkipListMap;
import java.util.concurrent.atomic.AtomicLong;

@SpringBootApplication
@RestController
@RequestMapping("/pessoas")
public class App {

    private final Map<Long, Pessoa> banco = new ConcurrentSkipListMap<>();
    private final AtomicLong seq = new AtomicLong();

    public static void main(String[] args) {
        SpringApplication.run(App.class, args);
    }

    public record Pessoa(Long id, String nome) {}

    @GetMapping
    public Collection<Pessoa> listar() {
        return banco.values();
    }

    @PostMapping
    public ResponseEntity<Pessoa> criar(@RequestBody Pessoa p) {
        if (p.nome() == null || p.nome().isBlank()) return ResponseEntity.badRequest().build();
        long id = seq.incrementAndGet();
        Pessoa nova = new Pessoa(id, p.nome().trim());
        banco.put(id, nova);
        return ResponseEntity.ok(nova);
    }

    @PutMapping("/{id}")
    public ResponseEntity<Pessoa> atualizar(@PathVariable Long id, @RequestBody Pessoa dados) {
        if (dados.nome() == null || dados.nome().isBlank()) return ResponseEntity.badRequest().build();
        Pessoa atualizada = banco.computeIfPresent(id, (k, v) -> new Pessoa(id, dados.nome().trim()));
        return atualizada != null ? ResponseEntity.ok(atualizada) : ResponseEntity.notFound().build();
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Void> deletar(@PathVariable Long id) {
        return banco.remove(id) != null ? ResponseEntity.noContent().build() : ResponseEntity.notFound().build();
    }
}
