    public ResponseEntity<Pessoa> criar(@RequestBody Pessoa p) {
        if (p.nome() == null || p.nome().isBlank()) return ResponseEntity.badRequest().build();
        long id = seq.incrementAndGet();
        Pessoa nova = new Pessoa(id, p.nome().trim());
        banco.put(id, nova);
        return ResponseEntity.ok(nova);
    }

    @PutMapping("/{id}")
    public ResponseEntity<Pessoa> atualizar(@PathVariable Long id, @RequestBody Pessoa dados) {
        if (dados.nome() == null || dados.nome().isBlank()) return ResponseEntity.badRequest().build();
